public class BestScore {
    public static void main(String[] args) {
        int score = 82;
        int best = 90;
        String name = "Ari";
        String bestName = "Mina";

        if (score > best)
            best = score;
            bestName = name; // runs every time - no braces

        System.out.println(best);
        System.out.println(bestName);
    }
}

public class BestScoreFixed {
    public static void main(String[] args) {
        int score = 82;
        int best = 90;
        String name = "Ari";
        String bestName = "Mina";

        if (score > best) {
            best = score;
            bestName = name;
        }

        System.out.println(best);
        System.out.println(bestName);
    }
}

